```{.r .cell-code}
# ── D2 pooled test (Li, Meng, Raghunathan & Rubin 1991, Stat. Sin. 1:65-92) ──
#
# Given M Wald chi-squared statistics W_1,...,W_M each with k df under H0,
# the D2 statistic is:
#
#   W̄   = mean(W_m)
#   b   = var(W_m)           sample variance across imputations
#
#   r2  = (1 + 1/M) * b / (2k)
#          ↑ between-imputation variance relative to the null variance
#            of chi2(k), which equals 2k (standardises the scale)
#
#   D2  = (W̄/k - r2) / (1 + r2)   ~ F(k, v2) under H0
#
#   v2  = (M - 1) * (1 + 1/r2)^2
#          → ∞ when r2 → 0 (no MI uncertainty: reduces to chi2(k)/k)
#          → (M-1) when r2 → ∞ (test overwhelmed by imputation variance)

d2_test <- function(chi2_vals, k) {
  M    <- length(chi2_vals)
  Wbar <- mean(chi2_vals)
  b    <- var(chi2_vals)

  r2   <- (1 + 1/M) * b / (2 * k)
  D2   <- (Wbar / k - r2) / (1 + r2)

  # Guard: if all imputations give identical statistics r2 = 0 exactly,
  # v2 → ∞ and the test reduces to the standard chi-squared
  v2   <- if (r2 < .Machine$double.eps * 100) Inf else (M - 1) * (1 + 1/r2)^2
  p    <- pf(D2, df1 = k, df2 = v2, lower.tail = FALSE)

  tibble(
    D2        = D2,
    df1       = k,
    df2       = v2,
    p.value   = p,
    r2        = r2,
    chi2_bar  = Wbar,
    chi2_var  = b,
    M         = M
  )
}

# ── Step 1: per-imputation Wald chi-squared ───────────────────────────────────
mundlak_terms <- c("m_polity", "m_lpop", "m_lgdppc")
k             <- length(mundlak_terms)    # 3 restrictions

chi2_vals <- vapply(a_mundlak$imputations, function(d) {
  fit <- plm(mundlak_formula, data = d,
             index = c("country", "year"), model = "random")
  bvec <- coef(fit)[mundlak_terms]
  Vmat <- vcov(fit)[mundlak_terms, mundlak_terms]
  as.numeric(t(bvec) %*% solve(Vmat) %*% bvec)    # W_m ~ chi2(k) under H0
}, numeric(1))

cat(sprintf(
  "Per-imputation Wald chi2(%d): mean = %.3f  SD = %.3f  range = [%.3f, %.3f]\n",
  k, mean(chi2_vals), sd(chi2_vals), min(chi2_vals), max(chi2_vals)
))
