  ) |>
  tab_footnote(
    footnote  = "r₂ = (1 + 1/M) · Var(W) / (2k): relative between-imputation variance.",
    locations = cells_column_labels(columns = r2)
  ) |>
  tab_footnote(
    footnote  = "v₂ = (M − 1)(1 + 1/r₂)²: shrinks toward M − 1 as MI uncertainty grows.",
    locations = cells_column_labels(columns = df2)
  )
